import type { VideoSource } from 'expo-video';
import type { ConquerRequest } from '@/store/slices/userSlice';
import { endpoints, getApiUrl } from '@/utils/constants';

const REQUEST_TIMEOUT_MS = 30_000;

/** An exposure video generated by the backend (GET /api/videos/{id}/). */
export type ExposureVideo = {
  id: number;
  fear_name: string;
  intensity: number;
  status: 'pending' | 'generating' | 'ready' | 'failed';
  error_message: string;
  /** Set once the video is ready. Stream it with the Authorization header. */
  stream_url: string | null;
  /** The session length the user chose. */
  duration_seconds: number | null;
  /** The generated clip's length; shorter than the session when the clip loops. */
  clip_duration_seconds: number | null;
};

type CallOptions = { method?: 'GET' | 'POST'; body?: object; signal?: AbortSignal };

async function call(path: string, token: string, { method = 'GET', body, signal }: CallOptions) {
  const controller = new AbortController();
  const cancel = () => controller.abort();
  if (signal?.aborted) cancel();
  signal?.addEventListener('abort', cancel);
  const timeout = setTimeout(cancel, REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(getApiUrl(path), {
      method,
      headers: { Authorization: `Token ${token}`, 'Content-Type': 'application/json' },
      body: body ? JSON.stringify(body) : undefined,
      signal: controller.signal,
    });
    const result = await response.json().catch(() => null);
    if (!response.ok) {
      throw new Error(
        firstMessage(result) ?? `The video service returned HTTP ${response.status}.`
      );
    }
    return result as ExposureVideo;
  } catch (error) {
    if (controller.signal.aborted && !signal?.aborted) {
      throw new Error('The video service did not respond. Check your connection and try again.');
    }
    throw error;
  } finally {
    clearTimeout(timeout);
    signal?.removeEventListener('abort', cancel);
  }
}

function firstMessage(result: unknown) {
  if (!result || typeof result !== 'object') return undefined;
  const message = Object.values(result)
    .flat()
    .find((value) => typeof value === 'string');
  return typeof message === 'string' ? message : undefined;
}

/**
 * Ask the backend to generate a video for this conquer request. Reusing `requestKey` returns
 * the same video, so retries never pay for a second generation.
 */
export function requestExposureVideo(
  request: ConquerRequest,
  requestKey: string,
  token: string,
  signal?: AbortSignal
) {
  return call(endpoints.videos, token, {
    method: 'POST',
    body: {
      fear: request.fear,
      intensity: request.intensity,
      duration_seconds: request.durationSeconds,
      request_key: requestKey,
    },
    signal,
  });
}

export function getExposureVideo(id: number, token: string, signal?: AbortSignal) {
  return call(`${endpoints.videos}${id}/`, token, { signal });
}

/** Player source that streams the video from the backend using HTTP range requests. */
export function exposureVideoSource(streamUrl: string, token: string): VideoSource {
  return { uri: streamUrl, headers: { Authorization: `Token ${token}` } };
}
